```javascript
import { uv, mix, uniform, length, smoothstep, fract, abs } from 'three/tsl';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  const timelines = [];
  const materials = [];
  const geometries = [];

  // Panel dimensions
  const panelW = 3.2;
  const panelH = 2.2;

  // Colors from spec
  const col = {
    bgStart: new THREE.Color(0x14141a),
    bgEnd: new THREE.Color(0x0b0b10),
    grid: new THREE.Color(0xe8ecf2),
    border: new THREE.Color(0x26262f),
    accent: new THREE.Color(0xff2a38),
    ink: new THREE.Color(0x16161d),
    paper: new THREE.Color(0xe8ecf2),
    btnTop: new THREE.Color(0xff4450),
    btnBot: new THREE.Color(0xc1121f)
  };

  // ===== 1. PANEL BACKGROUND WITH RADIAL GRADIENT AND GRID =====
  const panelGeom = new THREE.PlaneGeometry(panelW, panelH);
  geometries.push(panelGeom);

  const panelUV = uv();

  // Radial gradient from center
  const distFromCenter = length(panelUV.sub(0.5).mul(2.0));
  const baseGradient = mix(
    uniform(col.bgStart),
    uniform(col.bgEnd),
    smoothstep(0, 1, distFromCenter)
  );

  // Grid overlay (0.25-unit pitch at 6% opacity)
  const gridFreq = panelW / 0.25;
  const gridUV = panelUV.mul(gridFreq);
  const gridFrac = fract(gridUV);
  const gridDist = abs(gridFrac.sub(0.5)).mul(2.0);
  const gridLine = smoothstep(0.01, 0.005, gridDist);

  const panelColor = mix(
    baseGradient,
    uniform(col.grid),
    gridLine.mul(0.06)
  );

  const panelMat = new MeshBasicNodeMaterial();
  panelMat.colorNode = panelColor;
  materials.push(panelMat);

  const panelMesh = new THREE.Mesh(panelGeom, panelMat);
  group.add(panelMesh);

  // ===== 2. HAIRLINE BORDER =====
  const borderGeom = new THREE.EdgesGeometry(panelGeom);
  geometries.push(borderGeom);

  const borderMat = new THREE.LineBasicMaterial({
    color: col.border,
    transparent: true
  });
  materials.push(borderMat);

  const borderLine = new THREE.LineSegments(borderGeom, borderMat);
  borderLine.position.z = 0.001;
  group.add(borderLine);

  // ===== 3. GHOST PREVIEW (LEFT OF CENTER) =====
  const ghostGroup = new THREE.Group();
  ghostGroup.position.x = -0.75;
  ghostGroup.position.y = 0;

  // Ghost card outline: 1.1w x 1.4h
  const cardW = 1.1;
  const cardH = 1.4;

  const cardPoints = [
    new THREE.Vector3(-cardW / 2, -cardH / 2, 0),
    new THREE.Vector3(cardW / 2, -cardH / 2, 0),
    new THREE.Vector3(cardW / 2, cardH / 2, 0),
    new THREE.Vector3(-cardW / 2, cardH / 2, 0),
    new THREE.Vector3(-cardW / 2, -cardH / 2, 0)
  ];

  const cardGeom = new THREE.BufferGeometry().setFromPoints(cardPoints);
  geometries.push(cardGeom);

  const ghostLineMat = new THREE.LineBasicMaterial({
    color: col.paper,
    transparent: true,
    opacity: 0.3
  });
  materials.push(ghostLineMat);

  const cardLine = new THREE.Line(cardGeom, ghostLineMat);
  ghostGroup.add(cardLine);

  // Ghost dial circle: 0.55 diameter
  const dialRadius = 0.275;
  const dialPoints = [];
  for (let i = 0; i <= 64; i++) {
    const angle = (i / 64) * Math.PI * 2;
    dialPoints.push(new THREE.Vector3(
      Math.cos(angle) * dialRadius,
      Math.sin(angle) * dialRadius,
      0
    ));
  }

  const dialGeom = new THREE.BufferGeometry().setFromPoints(dialPoints);
  geometries.push(dialGeom);

  const dialLine = new THREE.Line(dialGeom, ghostLineMat);
  dialLine.position.y = 0.3;
  ghostGroup.add(dialLine);

  // Ghost text bars: 0.7w x 0.06h, two bars
  const barW = 0.7;
  const barH = 0.06;

  const barMat = new THREE.LineBasicMaterial({
    color: col.paper,
    transparent: true,
    opacity: 0.22
  });
  materials.push(barMat);

  for (let i = 0; i < 2; i++) {
    const barPoints = [
      new THREE.Vector3(-barW / 2, -barH / 2, 0),
      new THREE.Vector3(barW / 2, -barH / 2, 0),
      new THREE.Vector3(barW / 2, barH / 2, 0),
      new THREE.Vector3(-barW / 2, barH / 2, 0),
      new THREE.Vector3(-barW / 2, -barH / 2, 0)
    ];

    const barGeom = new THREE.BufferGeometry().setFromPoints(barPoints);
    geometries.push(barGeom);

    const barLine = new THREE.Line(barGeom, barMat);
    barLine.position.y = -0.35 - i * 0.15;
    ghostGroup.add(barLine);
  }

  // Breathing animation for ghost group (0.24 -> 0.34 opacity)
  const breatheTimeline = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTimeline
    .to(ghostLineMat, {
      opacity: 0.3 * (0.34 / 0.24),
      duration: 2.4,
      ease: 'cubic-bezier(0.445, 0.05, 0.55, 0.95)'
    }, 0)
    .to(barMat, {
      opacity: 0.22 * (0.34 / 0.24),
      duration: 2.4,
      ease: 'cubic-bezier(0.445, 0.05, 0.55, 0.95)'
    }, 0);

  timelines.push(breatheTimeline);
  group.add(ghostGroup);

  // ===== 4. TEXT COLUMN (RIGHT OF GHOST) =====
  const textGroup = new THREE.Group();
  textGroup.position.x = 0.3;
  textGroup.position.y = 0.3;

  // Headline
  const headline = ctx.fontAtlas.createText('Your ledger is empty.', {
    fontSize: 0.34,
    color: col.paper,
    align: 'left'
  });
  headline.position.y = 0.5;
  headline.position.x = 0;
  textGroup.add(headline);

  // Body copy
  const body = ctx.fontAtlas.createText('Commissioned pieces and saved references will appear here once you begin.', {
    fontSize: 0.13,
    color: col.paper,
    align: 'left',
    maxWidthPx: 280
  });
  body.position.y = -0.15;
  body.position.x = 0;
  textGroup.add(body);

  group.add(textGroup);

  // ===== 5. CTA BUTTON =====
  const btnW = 1.5;
  const btnH = 0.36;

  const btnGeom = new THREE.PlaneGeometry(btnW, btnH);
  geometries.push(btnGeom);

  const btnUV = uv();
  const btnGrad = mix(
    uniform(col.btnTop),
    uniform(col.btnBot),
    btnUV.y.add(0.5)
  );

  const btnMat = new MeshStandardNodeMaterial();
  btnMat.colorNode = btnGrad;
  btnMat.emissive = col.accent;
  btnMat.emissiveIntensity = 1.5;
  btnMat.roughness = 0.65;
  btnMat.metalness = 0;
  materials.push(btnMat);

  const btnMesh = new THREE.Mesh(btnGeom, btnMat);
  btnMesh.position.x = 0.3;
  btnMesh.position.y = -0.75;
  btnMesh.position.z = 0.001;

  const btnLabel = ctx.fontAtlas.createText('BROWSE THE COLLECTION', {
    fontSize: 0.13,
    color: col.ink,
    align: 'center',
    letterSpacingPx: 1.0
  });
  btnLabel.position.z = 0.01;
  btnMesh.add(btnLabel);

  // Button interaction: press down and navigate
  btnMesh.userData.handlers = {
    click: () => {
      const pressTimeline = gsap.to(btnMesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
      });
      timelines.push(pressTimeline);

      // Spring back to 1.0
      gsap.to(btnMesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.12,
        delay: 0.12,
        ease: 'power2.out'
      });

      // Emit navigation event
      ctx.emit('navigate', { to: 'hub-collection' });
    }
  };

  group.add(btnMesh);

  // ===== 6. MOUNT ANIMATION (FADE-UP) =====
  group.opacity = 0;
  group.position.y = 0.2;

  const mountTimeline = gsap.to(group, {
    opacity: 1,
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
  });

  timelines.push(mountTimeline);

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    materials.forEach(mat => mat.dispose?.());
    geometries.forEach(geom => geom.dispose?.());
  };

  return group;
}
